package cn.sifangguan.hotelaios.finance;
import cn.sifangguan.hotelaios.shared.audit.AuditWriter;
import cn.sifangguan.hotelaios.shared.context.TenantPrincipal;
import cn.sifangguan.hotelaios.shared.db.TenantDatabaseContext;
import cn.sifangguan.hotelaios.shared.security.AccessPolicy;
import jakarta.validation.constraints.*;
import org.springframework.jdbc.core.namedparam.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import static cn.sifangguan.hotelaios.finance.FinanceV2Support.*;

@Service @Transactional
public class FinanceSupplyInvoiceControlService {
 public record Request(@NotNull UUID requestId,@NotNull UUID recognitionId,@Min(0) int expectedVersion,@NotBlank @Size(max=2000) String reason){}
 public record Review(@Min(0) int expectedVersion,boolean approved,@NotBlank @Size(max=2000) String note){}
 private final NamedParameterJdbcTemplate jdbc;private final TenantDatabaseContext database;private final AccessPolicy access;private final AuditWriter audit;
 public FinanceSupplyInvoiceControlService(NamedParameterJdbcTemplate jdbc,TenantDatabaseContext database,AccessPolicy access,AuditWriter audit){this.jdbc=jdbc;this.database=database;this.access=access;this.audit=audit;}
 public Map<String,Object> list(UUID recognitionId){var p=prepare("finance.read","finance.accounting.read","finance.review","finance.submit");var rec=recognition(p,recognitionId,false);return output(Map.of("uses",jdbc.queryForList("select * from fs_invoice_use where tenant_id=:tenant and recognition_id=:id order by id",base(p).addValue("id",recognitionId)),"items",jdbc.queryForList("select * from fs_invoice_release where tenant_id=:tenant and recognition_id=:id order by created_at desc,id",base(p).addValue("id",recognitionId)),"canRequest",p.actorId().equals(rec.get("applicant_id"))&&"PENDING".equals(rec.get("status")),"boundary","仅释放尚未用于正式确认的错票；已核算发票不得直接解占后再报销，必须原事项正式逆向及依赖处理。暂估只允许未正式转票的回退，原暂估和实物事实保留。"));}
 public Map<String,Object> request(Request in){var p=prepare("finance.submit");lockReceipt(p,in.recognitionId());var rec=recognition(p,in.recognitionId(),true);invoiceLock(p);String fingerprint=FinanceService.hash(json(in));var b=base(p).addValue("id",in.requestId());var old=jdbc.queryForList("select * from fs_invoice_release where tenant_id=:tenant and id=:id",b);if(!old.isEmpty()){if(!fingerprint.equals(old.getFirst().get("request_hash"))||!p.actorId().equals(old.getFirst().get("applicant_id")))throw conflict("释放请求编号已用于其他原始依据");return output(old.getFirst());}version(rec,in.expectedVersion());if(!p.actorId().equals(rec.get("applicant_id")))throw conflict("仅原匹配经办可提交错票释放申请");guard(p,rec);if(p.actorId().equals(rec.get("confirmer_id")))throw conflict("错票释放必须由独立原财务确认人审核");one("select id from user_account where tenant_id=:tenant and id=:reviewer and status='ACTIVE'",base(p).addValue("reviewer",rec.get("confirmer_id")));var uses=uses(p,in.recognitionId());if(uses.isEmpty())throw conflict("本次匹配没有仍占用的原票，不生成空释放");var snapshot=Map.of("recognition",output(rec),"uses",value(uses));jdbc.update("insert into fs_invoice_release(id,tenant_id,recognition_id,recognition_version,request_hash,reason,snapshot,applicant_id,reviewer_id) values(:id,:tenant,:recognition,:version,:hash,:reason,cast(:snapshot as jsonb),:actor,:reviewer)",b.addValue("recognition",in.recognitionId()).addValue("version",in.expectedVersion()).addValue("hash",fingerprint).addValue("reason",in.reason()).addValue("snapshot",json(snapshot)).addValue("reviewer",rec.get("confirmer_id")));jdbc.update("insert into notification(id,tenant_id,recipient_account_id,notification_type,title,content,source_type,source_id,idempotency_key) values(gen_random_uuid(),:tenant,:reviewer,\'FINANCE_INVOICE_RELEASE_REVIEW\',\'错选原票占用待独立释放审核\',:reason,\'FINANCE_SUPPLY_INVOICE_RELEASE\',:id,:noticeKey) on conflict(tenant_id,recipient_account_id,idempotency_key) do nothing",b.addValue("noticeKey","fs-invoice-release:"+in.requestId()));audit.record("FINANCE_SUPPLY_INVOICE_RELEASE_REQUESTED","FS_INVOICE_RELEASE",in.requestId(),json(in));return output(one("select * from fs_invoice_release where tenant_id=:tenant and id=:id",b));}
 public Map<String,Object> review(UUID id,Review in){var p=prepare("finance.review");var b=base(p).addValue("id",id);var initial=one("select * from fs_invoice_release where tenant_id=:tenant and id=:id",b);lockReceipt(p,FinanceV2Support.id(initial.get("recognition_id")));var rec=recognition(p,FinanceV2Support.id(initial.get("recognition_id")),true);invoiceLock(p);var release=one("select * from fs_invoice_release where tenant_id=:tenant and id=:id for update",b);version(release,in.expectedVersion());if(!"REVIEW".equals(release.get("status"))||!p.actorId().equals(release.get("reviewer_id"))||p.actorId().equals(release.get("applicant_id")))throw conflict("须原配置财务确认人独立处理当前错票释放申请");if(in.approved()){version(rec,((Number)release.get("recognition_version")).intValue());guard(p,rec);var oldSnapshot=map(release.get("snapshot"));if(!map(json(Map.of("uses",value(uses(p,FinanceV2Support.id(rec.get("id"))))))).get("uses").equals(oldSnapshot.get("uses")))throw conflict("原票占用集合已变化，请重新核对并申请，不能借旧审批释放其他原票");}
  jdbc.update("update fs_invoice_release set status=:status,reviewed_by=:actor,review_note=:note,reviewed_at=now(),version=version+1 where tenant_id=:tenant and id=:id",b.addValue("status",in.approved()?"APPROVED":"REJECTED").addValue("note",in.note()));
  if(in.approved()){b.addValue("recognition",rec.get("id"));jdbc.update("update fs_invoice_use set released_at=now(),release_id=:id where tenant_id=:tenant and recognition_id=:recognition and released_at is null",b);boolean estimated=jdbc.queryForObject("select count(*) from fa_source_event where tenant_id=:tenant and source_type='FS_PROCUREMENT' and source_id=:recognition and event_key like 'ESTIMATE%'",b,Long.class)>0;jdbc.update("update fs_recognition set status=:state,invoice_amount=null,invoice_ids='[]',lines='[]',differences='[]',confirmed_by=null,version=version+1,accounting_date=case when :estimated then coalesce((select min(accounting_date) from fa_source_event where tenant_id=:tenant and source_type='FS_PROCUREMENT' and source_id=:recognition),accounting_date) else accounting_date end where tenant_id=:tenant and id=:recognition",b.addValue("state",estimated?"ESTIMATED":"UNMATCHED").addValue("estimated",estimated));}
  audit.record("FINANCE_SUPPLY_INVOICE_RELEASE_REVIEWED","FS_INVOICE_RELEASE",id,json(in));return output(one("select * from fs_invoice_release where tenant_id=:tenant and id=:id",b));
 }
 private void guard(TenantPrincipal p,Map<String,Object> rec){if(!"PENDING".equals(rec.get("status")))throw conflict("仅正式转票确认前的错选原票可独立释放；已确认采购须先完成原事项逆向，不可仅解占后重复报销");var b=base(p).addValue("id",rec.get("id"));if(jdbc.queryForObject("select count(*) from fa_source_event where tenant_id=:tenant and source_type='FS_PROCUREMENT' and source_id=:id and event_key not like 'ESTIMATE%'",b,Long.class)>0||jdbc.queryForObject("select count(*) from fs_stock_valuation where tenant_id=:tenant and recognition_id=:id",b,Long.class)>0||jdbc.queryForObject("select count(*) from fs_return where tenant_id=:tenant and recognition_id=:id and status<>'REJECTED'",b,Long.class)>0||jdbc.queryForObject("select count(*) from fo_document where tenant_id=:tenant and (source_id=:id or details->>'supplyRecognitionId'=cast(:id as text)) and status not in ('REJECTED','CANCELLED')",b,Long.class)>0)throw conflict("原采购已有正式计价、退换、应付或后续依赖，不能只释放票号制造另一笔成本；请完成正式逆向与依赖核验");for(var use:uses(p,id(rec.get("id"))))FinanceInputTaxGuard.assertReleasable(jdbc,p,id(use.get("invoice_id")));}
 private List<Map<String,Object>> uses(TenantPrincipal p,UUID recognition){return jdbc.queryForList("select * from fs_invoice_use where tenant_id=:tenant and recognition_id=:id and released_at is null order by id",base(p).addValue("id",recognition));}
 private Map<String,Object> recognition(TenantPrincipal p,UUID id,boolean lock){var rec=one("select * from fs_recognition where tenant_id=:tenant and id=:id"+(lock?" for update":""),base(p).addValue("id",id));access.requireOrgScope(FinanceV2Support.id(rec.get("hotel_id")));if(!p.hasPermission("*")&&!p.hasPermission("finance.read")&&!p.hasPermission("finance.accounting.read")&&!p.actorId().equals(rec.get("applicant_id"))&&!p.actorId().equals(rec.get("confirmer_id")))throw missing();return rec;}
 private void lockReceipt(TenantPrincipal p,UUID recognition){var rec=one("select receipt_id from fs_recognition where tenant_id=:tenant and id=:id",base(p).addValue("id",recognition));jdbc.queryForObject("select pg_advisory_xact_lock(hashtextextended(:key,91))",Map.of("key",p.tenantId()+":receipt:"+rec.get("receipt_id")),Object.class);}
 private void invoiceLock(TenantPrincipal p){jdbc.queryForObject("select pg_advisory_xact_lock(hashtextextended(:key,69))",Map.of("key",p.tenantId()+":invoice-registry"),Object.class);}
 private TenantPrincipal prepare(String...permissions){access.requireAnyPermission(permissions);var p=access.principal();database.apply(p.tenantId());return p;}
 private Map<String,Object> one(String sql,MapSqlParameterSource b){var r=jdbc.queryForList(sql,b);if(r.isEmpty())throw missing();return r.getFirst();}
}
